function applyImageZoom(next,anchor){const stage=$('#zoom-stage'),canvas=$('#image-canvas'),oldWidth=canvas.getBoundingClientRect().width||stage.clientWidth,oldLeft=Math.max(0,(stage.clientWidth-oldWidth)/2);const x=anchor?.x??stage.clientWidth/2,y=anchor?.y??stage.clientHeight/2;const pointX=(stage.scrollLeft+x-oldLeft)/oldWidth;const oldTop=parseFloat(getComputedStyle(canvas).marginTop)||0,pointY=(stage.scrollTop+y-oldTop)/oldWidth;imageZoom=Math.max(.1,Math.min(8,next));const width=(imageFitWidth||stage.clientWidth)*imageZoom;canvas.style.width=width+'px';for(let i=0;i<2;i++)canvas.style.marginTop=Math.max(0,(stage.clientHeight-canvas.getBoundingClientRect().height)/2)+'px';const newTop=parseFloat(canvas.style.marginTop)||0,newLeft=Math.max(0,(stage.clientWidth-width)/2);stage.scrollLeft=pointX*width+newLeft-x;stage.scrollTop=pointY*width+newTop-y;$('#zoom-level').textContent=Math.round(imageZoom*100)+'%';}
