$('#zoom-stage').addEventListener('wheel',e=>{e.preventDefault();const rect=$('#zoom-stage').getBoundingClientRect();const delta=e.deltaY*(e.deltaMode===1?16:e.deltaMode===2?rect.height:1);applyImageZoom(imageZoom*Math.exp(-delta*.0015),{x:e.clientX-rect.left,y:e.clientY-rect.top})},{passive:false});
