 const body=qbankNode('div','question-card-content qbank-card-body'),meta=qbankNode('div','qbank-meta');meta.append(qbankNode('span','qbank-type-badge',({choice:'📝 選擇題','true-false':'⚖ 是非題',image:'🖼 圖片題'})[type]));if(q.folder){const tag=qbankNode('span','qbank-card-folder',q.folder);tag.title=q.folder;meta.append(tag)}const title=qbankNode('h3',type==='image'?'qbank-image-title':'qbank-prompt',type==='image'?q.title:q.prompt||q.title);title.title=title.textContent;body.append(meta,title);
