// Library presentation: preserve the original upload, CSV, edit and save handlers.
function createQbankUI(){
 const root=$('#library'),editor=$('#editor'),manager=$('#folder-manager');let editBaseline=null,editorType='image';root.append(editor,manager);for(const dialog of root.querySelectorAll('dialog'))dialog.classList.add('qbank-modal');
 const managerBody=qbankNode('div','qbank-modal-body');for(const child of [...manager.children])if(!child.classList.contains('close')&&child.tagName!=='H2')managerBody.append(child);managerBody.querySelector('p').textContent='編輯名稱、調整順序；各列操作會即時儲存。';const note=qbankNode('small','qbank-muted','刪除資料夾會保留題目與圖片，並移至未分類。');managerBody.querySelector('p').after(note);const managerFooter=qbankNode('div','qbank-modal-footer'),done=qbankNode('button','secondary','完成');done.type='button';done.onclick=()=>closeDialog('folder-manager');managerFooter.append(done);manager.append(managerBody,managerFooter);
 const csvBody=qbankNode('div','qbank-modal-body'),csvFooter=qbankNode('div','qbank-modal-footer'),csv=$('#csv-import-dialog');for(const child of [...csv.children]){if(child.tagName==='BUTTON')csvFooter.append(child);else if(child.tagName!=='H2')csvBody.append(child)}csv.append(csvBody,csvFooter);
 const form=$('#edit-form'),advanced=$('#qbank-advanced'),titleLabel=$('#qbank-edit-title-label');
 const signature=()=>JSON.stringify([...form.querySelectorAll('input:not([name=qbank-answer]),textarea,select')].map(i=>[i.id,i.value]));
 function answerCards(){const host=$('#qbank-answer-cards>div');const keys=editorType==='choice'?[...'ABCD']:['TRUE','FALSE'];if(host.children.length!==keys.length||host.firstElementChild?.dataset.answerKey!==keys[0]){host.replaceChildren();for(const key of keys){const label=qbankNode('label','qbank-answer-option');label.dataset.answerKey=key;const radio=document.createElement('input');radio.type='radio';radio.name='qbank-answer';radio.value=key;const copy=qbankNode('span','');radio.onchange=()=>{if(radio.checked)$('#edit-answer').value=key};label.append(radio,copy);host.append(label)}}for(const label of host.children){const key=label.dataset.answerKey,radio=label.querySelector('input'),copy=label.querySelector('span');radio.checked=$('#edit-answer').value.toUpperCase()===key;if(editorType==='choice'){const option=$('#edit-option-'+key).value;copy.textContent=key+' · '+(option||'未填選項');copy.title=copy.textContent;radio.disabled=!option.trim()}else{copy.textContent=key==='TRUE'?'○ 正確':'✕ 錯誤';radio.disabled=false}}}
 function editorOpened(q){closeMenus();editorType=questionType(q);editor.dataset.questionType=editorType;const image=editorType==='image';$('#qbank-edit-preview').hidden=!image;$('#qbank-edit-preview').replaceChildren();if(image){if(q.image){const img=new Image();img.src=q.image;img.alt=q.title;$('#qbank-edit-preview').append(img)}else $('#qbank-edit-preview').textContent=q.emoji||'✧';$('#qbank-main-title').append(titleLabel)}else advanced.append(titleLabel);advanced.hidden=image;advanced.open=false;$('#qbank-raw-answer').hidden=!image;$('#qbank-answer-cards').hidden=image;if(!image)answerCards();editBaseline=signature()}
 function editorDirty(){return editor.open&&editBaseline!==null&&signature()!==editBaseline}
 function canCloseEditor(){return !editorDirty()||confirm('尚有未儲存的挑戰變更，確定捨棄並關閉？')}
 editor.addEventListener('cancel',e=>{e.preventDefault();closeDialog('editor')});editor.addEventListener('close',()=>editBaseline=null);form.addEventListener('input',e=>{if(e.target.id.startsWith('edit-option-'))answerCards()});form.addEventListener('invalid',e=>{if(e.target.id==='edit-title')advanced.open=true},true);
 $('#qbank-edit-preview').onclick=()=>{const q=state.questions.find(q=>q.id===editing);if(q?.image)openImageViewer(q.image)};$('#qbank-delete-question').onclick=()=>{if(editing&&deleteQuestions(new Set([editing])))editor.close()};
 $('#folders').addEventListener('click',e=>{const button=e.target.closest('[data-qbank-folder]');if(!button)return;folder=button.dataset.qbankFolder;selected.clear();renderLibrary()});$('#qbank-type-filters').addEventListener('click',e=>{const button=e.target.closest('[data-qbank-type]');if(!button)return;qbankType=button.dataset.qbankType;selected.clear();renderQuestionGrid()});
 function toggleCard(card){const id=card.dataset.questionId;selected.has(id)?selected.delete(id):selected.add(id);updateBatch()}
 $('#question-grid').addEventListener('click',e=>{const card=e.target.closest('[data-question-id]');if(!card)return;const q=state.questions.find(q=>q.id===card.dataset.questionId);if(!q)return;if(e.target.matches('.qbank-check'))return;if(qbankSelecting){toggleCard(card);return}if(e.target.closest('[data-qbank-image]')&&q.image){closeMenus();openImageViewer(q.image)}else editQuestion(q)});
 $('#question-grid').addEventListener('change',e=>{if(qbankSelecting&&e.target.matches('.qbank-check')){const id=e.target.closest('[data-question-id]').dataset.questionId;e.target.checked?selected.add(id):selected.delete(id);updateBatch()}});
 $('#question-grid').addEventListener('keydown',e=>{if(e.isComposing||e.altKey||e.ctrlKey||e.metaKey||document.querySelector('dialog[open],:popover-open')||!['Enter',' '].includes(e.key)||!e.target.matches('[data-question-id]'))return;e.preventDefault();e.target.click()});
 function selectionMode(value){qbankSelecting=value;selected.clear();updateBatch()}
 $('#qbank-select-mode').onclick=()=>selectionMode(!qbankSelecting);$('#qbank-cancel-selection').onclick=()=>selectionMode(false);$('#qbank-empty-add').onclick=()=>$('#qbank-add').click();$('#qbank-empty-clear').onclick=()=>{$('#search').value='';qbankType='all';selected.clear();renderQuestionGrid()};
 const menus=[[$('#qbank-add-menu'),$('#qbank-add')],[$('#qbank-template-menu'),$('#qbank-templates')]];
 function closeMenus(){for(const [menu] of menus)if(menu.matches(':popover-open'))menu.hidePopover()}
 for(const [menu,trigger] of menus){menu.addEventListener('toggle',e=>{if(e.newState!=='open')return;const r=trigger.getBoundingClientRect(),w=menu.getBoundingClientRect().width;menu.style.left=Math.max(12,Math.min(innerWidth-w-12,r.right-w))+'px';menu.style.top=Math.max(12,Math.min(innerHeight-menu.getBoundingClientRect().height-12,r.bottom+8))+'px';menu.querySelector('button').focus({preventScroll:true})});menu.addEventListener('click',e=>{if(e.target.closest('button'))menu.hidePopover()});menu.addEventListener('keydown',e=>{if(e.isComposing||e.altKey||e.ctrlKey||e.metaKey)return;if(e.key==='Escape'){e.preventDefault();menu.hidePopover();trigger.focus();return}if(!['ArrowDown','ArrowUp','Home','End'].includes(e.key))return;const items=[...menu.querySelectorAll('button')],index=items.indexOf(document.activeElement);if(index<0)return;e.preventDefault();items[e.key==='Home'?0:e.key==='End'?items.length-1:(index+(e.key==='ArrowDown'?1:items.length-1))%items.length].focus()})}
 function footer(){const height=Math.max($('#batch').getBoundingClientRect().height,$('#library-events .event-settings-savebar').getBoundingClientRect().height);root.style.setProperty('--qbank-footer-space',height?height+24+'px':'24px')}
 const footerSize=new ResizeObserver(footer);footerSize.observe($('#batch'));footerSize.observe($('#library-events .event-settings-savebar'));
 function eventStatus(){const count=eventSettingsDirty?$$('#library-events .event-editor-row').length:state.events.chance.length+state.events.fate.length;qbankText($('#qbank-event-total'),count);qbankText($('#event-settings-status'),eventSettingsDirty?'● 有未儲存變更':'✓ 已儲存');$('#save-event-settings').classList.toggle('qbank-clean',!eventSettingsDirty);footer()}
 function tabChanged(){closeMenus();selected.clear();updateBatch();eventStatus()}
 return {editorOpened,canCloseEditor,editorDirty,footer,eventStatus,tabChanged};
}
